  "settings.answerPrompts.vlm_answer.title": "回答生成のプロンプト",
  "settings.answerPrompts.vlm_answer.description":
    "根拠と質問を回答モデルへ渡す指示のテンプレートです。全体で 1 つの設定で、保存した内容は次に検索した根拠から回答を生成するときに使います。登録済みQ&Aや回答前の確認の経路では使いません。",
