  "settings.answerPrompts.loading": "プロンプトを読み込んでいます",
  "settings.answerPrompts.loadError": "プロンプトを読み込めませんでした。",
  "settings.retrieval.prompts.title": "検索に使うプロンプト",
  "settings.retrieval.prompts.description": "質問の解釈、検索、根拠の判定ごとに、使う条件とモデルに渡す指示を確認できます。表示順は処理の目安です。設定や検索結果によって省略・再実行され、CRAG では検索と判定を繰り返す場合があります。各指示を編集し、保存すると次の処理から反映されます。",
  "settings.answerPrompts.stages.title": "処理の各段のプロンプト",
  "settings.answerPrompts.stages.description":
    "回答生成・監査・資料との照合ごとに、使う条件と指示を示します。設定や判定によって省略・再生成される場合があります。検索関連の指示は「検索方法」、品質評価の指示は「評価の基準」、文書解析・文書分割の指示は各設定画面で確認します。各段の中はモデルへ渡す順です。業務ガイドの準備は独立した処理で、Q&A は検索による回答とは別の経路です。各指示を編集・保存できます。",
  "settings.answerPrompts.phase.ingestion": "文書解析",
  "settings.answerPrompts.phase.question": "質問の解釈",
  "settings.answerPrompts.phase.retrieval": "検索",
  "settings.answerPrompts.phase.grounding": "根拠の判定",
  "settings.answerPrompts.phase.generation": "回答の生成",
  "settings.answerPrompts.phase.audit": "監査",
  "settings.answerPrompts.phase.evaluation": "評価",
  "settings.answerPrompts.phase.indexing": "文書分割・索引",
  "settings.answerPrompts.phase.knowledge": "業務ガイドの準備",
  "settings.answerPrompts.phase.ingestion.description": "ファイル準備の後、図・画像の読み取り、見出しの階層、項目抽出、章節の要約の順です。図の先読みが解析と並行する場合があります。",
  "settings.answerPrompts.phase.indexing.description": "文書分割の後に、任意の RAPTOR の階層の要約を作り、索引へ進みます。ファイル準備・通常の分割・埋め込み・文書構造索引の構築は LLM プロンプトを使いません。",
  "settings.answerPrompts.phase.knowledge.description": "回答で使う業務ガイドを準備する独立した処理です。文書の取込ごとに実行するものではありません。",
  "settings.answerPrompts.phase.question.description": "業務ガイドの条件確認、会話を踏まえた書き換え、項目の条件、検索戦略と検索文の順です。対象外の段は省略します。",
  "settings.answerPrompts.phase.retrieval.description": "検索候補を集めた後、必要に応じて画面目録から根拠を足します。",
  "settings.answerPrompts.phase.grounding.description": "取得した根拠を判定・補完します。CRAG は再検索や章節の拡張の途中で判定を繰り返すため、一方向に一度だけ進む処理ではありません。",
  "settings.answerPrompts.phase.generation.description": "登録済みQ&Aを選んだ場合は Q&A の経路、それ以外は検索した根拠による生成です。後者の システムプロンプトと入力テンプレートをこの順に示します。",
  "settings.answerPrompts.phase.audit.description": "回答の生成後に使う監査・資料との照合の指示です。RAG では LLM 監査が有効なときに使います（既定は無効）。MCP の資料との照合は独立して呼び出します。",
  "settings.evaluation.prompts.title": "品質評価のプロンプト",
  "settings.evaluation.prompts.description": "品質評価と保存した回答の評価で使う指示を編集・保存します。",
  "settings.answerPrompts.phase.evaluation.description": "品質評価では、利用できる標準回答・必須要点・取得した根拠に応じて、モデルが回答の網羅性・忠実性・正確性を判定します。必要な情報がない指標や判定を完了できない指標は未評価です。検索と応答判断の指標はコードで計算します。資料との照合は回答プロンプトで確認できます。",
  "settings.answerPrompts.condition": "使われる条件: {condition}",
  "settings.answerPrompts.fixedRules": "図・画像の指示と出力形式",
  "settings.answerPrompts.visionInstructions.description": "保存した指示は次の画像の読み取りから使います。処理済みの文書への反映には再処理が必要です。出力形式と上限は読み取り専用です。保存済みの出力例を編集しても、固定の項目・型・件数上限は変わりません。",
  "settings.answerPrompts.noPlaceholders": "必須の placeholder はありません。",
  "settings.answerPrompts.heading_levels.title": "見出しの階層の推定プロンプト",
  "settings.answerPrompts.heading_levels.description": "「見出しの階層の推定（AI）」が有効で、対象の条件を満たす文書に使います。保存した内容は次の処理から使い、処理済みの文書には再処理するまで反映しません。",
  "settings.answerPrompts.heading_levels.field": "プロンプト",
  "settings.answerPrompts.field_extraction.title": "メタデータ/項目抽出プロンプト",
  "settings.answerPrompts.field_extraction.description": "「メタデータ/項目抽出」が有効なときに、本文の単位ごとに渡す指示です。項目の定義は実行時に追加します。 保存した内容は次の処理から使い、処理済みの文書には再処理するまで反映しません。",
  "settings.answerPrompts.field_extraction.field": "プロンプト",
  "settings.answerPrompts.navigation_summary.title": "章節の要約プロンプト",
  "settings.answerPrompts.navigation_summary.description": "文書解析の「章節の要約」が有効なときに、章節ごとに使います。保存した内容は次の処理から使い、処理済みの文書には再処理するまで反映しません。",
  "settings.answerPrompts.navigation_summary.field": "プロンプト",
  "settings.answerPrompts.raptor_summary_system.title": "RAPTOR の階層の要約のシステムプロンプト",
  "settings.answerPrompts.raptor_summary_system.description": "文書分割後、RAPTOR の階層の要約が有効なときに使う共通の指示です。保存した内容は次の処理から使い、処理済みの文書には再処理するまで反映しません。",
  "settings.answerPrompts.raptor_summary_system.field": "プロンプト",
  "settings.raptor.description": "文書解析の章節の要約の後、文書を Chunk に分割してから、RAPTOR で階層ごとの要約を作り、Embedding・索引へ進みます。章節の要約とは独立した機能です。この設定を有効にすると、次の取込・再処理から実行します。既定は無効です。",
  "settings.answerPrompts.stage.picture_description": "図・画像の説明",
  "settings.answerPrompts.stage.picture_description.condition":
    "「図・画像を AI で読み取る」を有効にしたとき（図・表の画像ごと）。指示は文書解析の「図・画像の読み取りプロンプト」で編集します。出力形式と上限は読み取り専用です。",
  "settings.answerPrompts.stage.heading_levels": "見出しの階層を推定する",
  "settings.answerPrompts.stage.heading_levels.condition":
    "解析後の処理の「見出しの階層の推定（AI）」を有効にし、Docling の解析結果で、しおりの階層を使えず、階層が未判定の見出しの割合と見出し数が設定の条件を満たすとき（文書ごと。再試行あり）",
  "settings.answerPrompts.stage.field_extraction": "文書から項目を抽出する",
